export function findTemplateByKey(candidateKey: string): RecommendationTemplate | null {
  return RECOMMENDATION_TEMPLATES.find((t) => t.candidateKey === candidateKey) ?? null;
}

export function templatesForDimension(dimensionKey: string): RecommendationTemplate[] {
  return RECOMMENDATION_TEMPLATES.filter((t) => t.dimensionKey === dimensionKey);
}
